function validate([edges]) {
  if (!Array.isArray(edges) || edges.length < 2 || edges.length > 100000) return 'edges needs 2 to 10^5 entries.';
  const n = edges.length;
  for (let i = 0; i < n; i++) {
    if (!Number.isInteger(edges[i]) || edges[i] < 0 || edges[i] >= n) return 'Each edges[i] is a node from 0 to n - 1.';
    if (edges[i] === i) return 'A node cannot point to itself.';
  }
  return null;
}

