function edgeScore(edges) {
  const score = new Array(edges.length).fill(0);

  for (let i = 0; i < edges.length; i++) {
    score[edges[i]] += i;
  }

  let best = 0;
  for (let node = 1; node < edges.length; node++) {
    if (score[node] > score[best]) {
      best = node;
    }
  }
  return best;
}

