function edgeScore(edges) {
  // For every candidate node, add up the labels of the nodes pointing to it from scratch.
  let answer = -1;
  let answerScore = -1;
  for (let target = 0; target < edges.length; target++) {
    let total = 0;
    for (let from = 0; from < edges.length; from++) if (edges[from] === target) total += from;
    if (total > answerScore) { answerScore = total; answer = target; }
  }
  return answer;
}

