function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'small' ? pick(2, 8) : pick(1500, 2000);
  const hubs = Array.from({ length: pick(1, size === 'small' ? 3 : 20) }, () => pick(0, n - 1));
  const concentrated = rand() < 0.5;
  const edges = [];
  for (let i = 0; i < n; i++) {
    let target = concentrated ? hubs[pick(0, hubs.length - 1)] : pick(0, n - 1);
    while (target === i) target = pick(0, n - 1);
    edges.push(target);
  }
  return [edges];
}
